from __future__ import annotations

import pandas as pd
from pandas._libs import lib as pandas_lib

from .generic import patch_method


def _combine_series_results(results: list[object], index: pd.Index, name):
    if not results:
        return pd.Series(index=index, name=name, dtype="float64")

    first = results[0]
    combined = pd.concat(results, axis=0)
    if isinstance(first, pd.Series):
        combined = combined.reindex(index)
        combined.name = name
        return combined
    return combined.reindex(index=index)


def _series_apply_chunk(payload: dict):
    series = payload["series"]
    kwargs = dict(payload["kwargs"])

    if payload["convert_dtype"] is pandas_lib.no_default:
        return series.apply(
            payload["func"],
            args=payload["args"],
            by_row=payload["by_row"],
            **kwargs,
        )

    return series.apply(
        payload["func"],
        convert_dtype=payload["convert_dtype"],
        args=payload["args"],
        by_row=payload["by_row"],
        **kwargs,
    )


def _series_map_chunk(payload: dict):
    return payload["series"].map(payload["arg"], na_action=payload["na_action"])


def parallel_apply(
    self,
    func,
    convert_dtype=pandas_lib.no_default,
    args=(),
    *,
    by_row="compat",
    **kwargs,
):
    from pandarallel.core import get_runtime_config, run_parallel_tasks
    from pandarallel.utils import chunk_slices

    task_slices = chunk_slices(len(self.index), get_runtime_config().nb_workers)
    if len(task_slices) <= 1:
        if convert_dtype is pandas_lib.no_default:
            return self.apply(func, args=args, by_row=by_row, **kwargs)
        return self.apply(
            func,
            convert_dtype=convert_dtype,
            args=args,
            by_row=by_row,
            **kwargs,
        )

    payloads = [
        {
            "series": self.iloc[task_slice],
            "func": func,
            "convert_dtype": convert_dtype,
            "args": args,
            "by_row": by_row,
            "kwargs": kwargs,
        }
        for task_slice in task_slices
    ]

    results = run_parallel_tasks(_series_apply_chunk, payloads, description="Series.apply")
    return _combine_series_results(results, self.index, self.name)


def parallel_map(self, arg, na_action=None):
    from pandarallel.core import get_runtime_config, run_parallel_tasks
    from pandarallel.utils import chunk_slices

    task_slices = chunk_slices(len(self.index), get_runtime_config().nb_workers)
    if len(task_slices) <= 1:
        return self.map(arg, na_action=na_action)

    payloads = [
        {"series": self.iloc[task_slice], "arg": arg, "na_action": na_action}
        for task_slice in task_slices
    ]

    results = run_parallel_tasks(_series_map_chunk, payloads, description="Series.map")
    combined = pd.concat(results, axis=0).reindex(self.index)
    combined.name = self.name
    return combined


def install() -> None:
    patch_method(pd.Series, "parallel_apply", parallel_apply)
    patch_method(pd.Series, "parallel_map", parallel_map)

