from __future__ import annotations

import logging
import multiprocessing as mp
import os
import tempfile
import traceback
from concurrent.futures import ProcessPoolExecutor, as_completed
from dataclasses import asdict, dataclass
from typing import Any, Callable, Sequence

import dill

from .progress_bars import create_progress_bar
from .utils import get_nb_physical_cores, is_memory_fs_available, running_in_worker

MEMORY_FS_ROOT = os.environ.get("MEMORY_FS_ROOT", "/dev/shm")
NB_PHYSICAL_CORES = get_nb_physical_cores()

LOGGER = logging.getLogger("pandarallel")
if not LOGGER.handlers:
    _handler = logging.StreamHandler()
    _handler.setFormatter(logging.Formatter("pandarallel: %(levelname)s: %(message)s"))
    LOGGER.addHandler(_handler)
LOGGER.propagate = False


class PandarallelError(RuntimeError):
    pass


class MemoryFileSystemUnavailableError(PandarallelError):
    pass


class ParallelExecutionError(PandarallelError):
    pass


@dataclass
class ParallelConfig:
    nb_workers: int = NB_PHYSICAL_CORES
    progress_bar: bool = False
    verbose: int = 2
    use_memory_fs: bool = False
    memory_fs_root: str = MEMORY_FS_ROOT
    transport: str = "pipe"


_CONFIG = ParallelConfig()


def _configure_logger(verbose: int) -> None:
    if verbose <= 0:
        LOGGER.setLevel(logging.CRITICAL + 1)
    elif verbose == 1:
        LOGGER.setLevel(logging.WARNING)
    else:
        LOGGER.setLevel(logging.INFO)


def _resolve_memory_fs_mode(use_memory_fs: bool | None, root: str) -> tuple[bool, str]:
    available = is_memory_fs_available(root)
    if use_memory_fs is True and not available:
        raise MemoryFileSystemUnavailableError(
            f"Memory file system is unavailable at {root!r}."
        )

    enabled = available if use_memory_fs is None else bool(use_memory_fs)
    return enabled, "memory_fs" if enabled else "pipe"


def get_runtime_config() -> ParallelConfig:
    return _CONFIG


def get_config() -> dict[str, Any]:
    return asdict(_CONFIG)


def _dump_to_file(payload: Any, root: str, prefix: str) -> str:
    file_descriptor, path = tempfile.mkstemp(prefix=prefix, suffix=".dill", dir=root)
    os.close(file_descriptor)
    with open(path, "wb") as handle:
        dill.dump(payload, handle)
    return path


def _load_from_file(path: str) -> Any:
    try:
        with open(path, "rb") as handle:
            return dill.load(handle)
    finally:
        try:
            os.remove(path)
        except OSError:
            pass


def _serialize_transport(payload: Any, config: ParallelConfig, prefix: str):
    if config.transport == "memory_fs":
        return _dump_to_file(payload, config.memory_fs_root, prefix)
    return dill.dumps(payload)


def _deserialize_transport(payload_ref: Any, transport: str) -> Any:
    if transport == "memory_fs":
        return _load_from_file(payload_ref)
    return dill.loads(payload_ref)


def _make_error_payload(exception: BaseException) -> dict[str, Any]:
    payload: dict[str, Any] = {
        "exception_bytes": None,
        "exception_type": type(exception).__name__,
        "exception_repr": repr(exception),
        "traceback": traceback.format_exc(),
    }
    try:
        payload["exception_bytes"] = dill.dumps(exception)
    except Exception:
        payload["exception_bytes"] = None
    return payload


def _raise_remote_exception(response: dict[str, Any]) -> None:
    exception_bytes = response.get("exception_bytes")
    if exception_bytes is not None:
        exception = dill.loads(exception_bytes)
        remote_traceback = response.get("traceback")
        if remote_traceback:
            exception.args = (
                *exception.args,
                f"Remote traceback:\n{remote_traceback}",
            )
        raise exception

    raise ParallelExecutionError(
        f"{response.get('exception_type', 'Exception')}: "
        f"{response.get('exception_repr', 'Unknown worker error')}\n"
        f"{response.get('traceback', '')}"
    )


def _worker_entry(task_ref, transport: str, root: str):
    task = _deserialize_transport(task_ref, transport)
    try:
        handler = dill.loads(task["handler_bytes"])
        result = handler(task["payload"])
        response = {"order": task["order"], "ok": True, "result": result}
    except BaseException as exception:
        response = {"order": task["order"], "ok": False, **_make_error_payload(exception)}

    if transport == "memory_fs":
        return _dump_to_file(response, root, "pandarallel_result_")
    return dill.dumps(response)


def _run_tasks_sequential(
    handler: Callable[[Any], Any],
    payloads: Sequence[Any],
    description: str,
    config: ParallelConfig,
) -> list[Any]:
    results = [None] * len(payloads)
    progress = create_progress_bar(
        total=len(payloads),
        enabled=config.progress_bar,
        description=description,
    )
    with progress:
        for order, payload in enumerate(payloads):
            results[order] = handler(payload)
            progress.update()
    return results


def run_parallel_tasks(
    handler: Callable[[Any], Any],
    payloads: Sequence[Any],
    description: str = "Processing",
) -> list[Any]:
    config = get_runtime_config()

    if not payloads:
        return []

    if (
        config.nb_workers <= 1
        or len(payloads) <= 1
        or running_in_worker()
    ):
        return _run_tasks_sequential(handler, payloads, description, config)

    try:
        serialized_handler = dill.dumps(handler)
    except Exception as exception:
        LOGGER.warning(
            "Falling back to sequential execution because the task handler "
            "could not be serialized: %s",
            exception,
        )
        return _run_tasks_sequential(handler, payloads, description, config)

    try:
        task_refs = [
            _serialize_transport(
                {
                    "order": order,
                    "handler_bytes": serialized_handler,
                    "payload": payload,
                },
                config,
                "pandarallel_task_",
            )
            for order, payload in enumerate(payloads)
        ]
    except Exception as exception:
        LOGGER.warning(
            "Falling back to sequential execution because task payloads "
            "could not be prepared for worker transport: %s",
            exception,
        )
        return _run_tasks_sequential(handler, payloads, description, config)

    results = [None] * len(payloads)
    progress = create_progress_bar(
        total=len(payloads),
        enabled=config.progress_bar,
        description=description,
    )

    max_workers = min(config.nb_workers, len(payloads))
    completed = 0

    try:
        context = mp.get_context("spawn")
        with ProcessPoolExecutor(max_workers=max_workers, mp_context=context) as executor:
            future_to_order = {
                executor.submit(
                    _worker_entry,
                    task_ref,
                    config.transport,
                    config.memory_fs_root,
                ): order
                for order, task_ref in enumerate(task_refs)
            }

            with progress:
                for future in as_completed(future_to_order):
                    response = _deserialize_transport(future.result(), config.transport)
                    completed += 1
                    progress.update()
                    if not response["ok"]:
                        _raise_remote_exception(response)
                    results[response["order"]] = response["result"]

        return results
    except BaseException as exception:
        if completed == 0 and not isinstance(exception, PandarallelError):
            LOGGER.warning(
                "Falling back to sequential execution because worker startup "
                "failed: %s",
                exception,
            )
            return _run_tasks_sequential(handler, payloads, description, config)
        raise


class pandarallel:
    __version__ = "0.1.0"
    initialized = False
    nb_workers = _CONFIG.nb_workers
    progress_bar = _CONFIG.progress_bar
    verbose = _CONFIG.verbose
    use_memory_fs = _CONFIG.use_memory_fs
    transport = _CONFIG.transport

    @classmethod
    def initialize(
        cls,
        shm_size_mb=None,
        nb_workers=NB_PHYSICAL_CORES,
        progress_bar: bool = False,
        verbose: int = 2,
        use_memory_fs: bool | None = None,
    ) -> None:
        global _CONFIG

        if shm_size_mb is not None:
            LOGGER.warning("`shm_size_mb` is deprecated and ignored.")

        nb_workers = int(nb_workers)
        if nb_workers <= 0:
            raise ValueError("`nb_workers` must be a strictly positive integer.")

        _configure_logger(int(verbose))
        memory_fs_enabled, transport = _resolve_memory_fs_mode(
            use_memory_fs,
            MEMORY_FS_ROOT,
        )

        _CONFIG = ParallelConfig(
            nb_workers=nb_workers,
            progress_bar=bool(progress_bar),
            verbose=int(verbose),
            use_memory_fs=memory_fs_enabled,
            memory_fs_root=MEMORY_FS_ROOT,
            transport=transport,
        )

        _ensure_patched()

        cls.initialized = True
        cls.nb_workers = _CONFIG.nb_workers
        cls.progress_bar = _CONFIG.progress_bar
        cls.verbose = _CONFIG.verbose
        cls.use_memory_fs = _CONFIG.use_memory_fs
        cls.transport = _CONFIG.transport

        if _CONFIG.verbose >= 2:
            LOGGER.info(
                "Initialized with %s worker(s) using %s transport.",
                _CONFIG.nb_workers,
                _CONFIG.transport,
            )

    @classmethod
    def get_config(cls) -> dict[str, Any]:
        return get_config()


def initialize(*args, **kwargs) -> None:
    return pandarallel.initialize(*args, **kwargs)


def _ensure_patched() -> None:
    from .data_types import patch_all

    patch_all()


_ensure_patched()
_configure_logger(_CONFIG.verbose)

