from __future__ import annotations

import math
import multiprocessing
import os
from typing import Iterable, Sequence

import psutil


def get_nb_physical_cores() -> int:
    count = psutil.cpu_count(logical=False) or os.cpu_count() or 1
    return max(int(count), 1)


def is_memory_fs_available(root: str) -> bool:
    return os.path.isdir(root) and os.access(root, os.W_OK | os.X_OK)


def running_in_worker() -> bool:
    return multiprocessing.current_process().name != "MainProcess"


def chunk_slices(length: int, nb_chunks: int) -> list[slice]:
    if length <= 0:
        return []

    nb_chunks = max(1, min(int(nb_chunks), length))
    chunk_size = int(math.ceil(length / nb_chunks))
    return [
        slice(start, min(length, start + chunk_size))
        for start in range(0, length, chunk_size)
    ]


def chunk_sequence[T](values: Sequence[T], nb_chunks: int) -> list[list[T]]:
    if not values:
        return []

    slices = chunk_slices(len(values), nb_chunks)
    return [list(values[item]) for item in slices]


def normalize_worker_count(nb_workers: int | None) -> int:
    if nb_workers is None:
        return get_nb_physical_cores()
    return max(int(nb_workers), 1)

