from __future__ import annotations

import pandas as pd

from .generic import patch_method


def _combine_axis_zero(results: list[object], columns: pd.Index):
    if not results:
        return pd.Series(dtype="float64", index=columns)

    first = results[0]
    if isinstance(first, pd.Series):
        combined = pd.concat(results, axis=0)
        return combined.reindex(columns)

    return pd.concat(results, axis=1).reindex(columns=columns)


def _combine_axis_one(results: list[object], index: pd.Index):
    if not results:
        return pd.Series(dtype="float64", index=index)

    first = results[0]
    combined = pd.concat(results, axis=0)
    if isinstance(first, pd.Series):
        return combined.reindex(index)
    return combined.reindex(index=index)


def _apply_chunk(payload: dict):
    frame = payload["frame"]
    return frame.apply(
        payload["func"],
        axis=payload["axis"],
        raw=payload["raw"],
        result_type=payload["result_type"],
        args=payload["args"],
        by_row=payload["by_row"],
        engine=payload["engine"],
        engine_kwargs=payload["engine_kwargs"],
        **payload["kwargs"],
    )


def _applymap_chunk(payload: dict):
    frame = payload["frame"]
    mapper = getattr(frame, "map", None)
    if mapper is not None:
        return mapper(
            payload["func"],
            na_action=payload["na_action"],
            **payload["kwargs"],
        )

    return frame.applymap(
        payload["func"],
        na_action=payload["na_action"],
        **payload["kwargs"],
    )


def parallel_apply(
    self,
    func,
    axis=0,
    raw: bool = False,
    result_type=None,
    args=(),
    by_row="compat",
    engine: str = "python",
    engine_kwargs=None,
    **kwargs,
):
    if engine != "python":
        return self.apply(
            func,
            axis=axis,
            raw=raw,
            result_type=result_type,
            args=args,
            by_row=by_row,
            engine=engine,
            engine_kwargs=engine_kwargs,
            **kwargs,
        )

    from pandarallel.core import get_runtime_config, run_parallel_tasks
    from pandarallel.utils import chunk_slices

    axis_number = self._get_axis_number(axis)
    config = get_runtime_config()

    chunk_axis_size = len(self.columns) if axis_number == 0 else len(self.index)
    task_slices = chunk_slices(chunk_axis_size, config.nb_workers)
    if len(task_slices) <= 1:
        return self.apply(
            func,
            axis=axis_number,
            raw=raw,
            result_type=result_type,
            args=args,
            by_row=by_row,
            engine=engine,
            engine_kwargs=engine_kwargs,
            **kwargs,
        )

    payloads = []
    for task_slice in task_slices:
        chunk = self.iloc[:, task_slice] if axis_number == 0 else self.iloc[task_slice, :]
        payloads.append(
            {
                "frame": chunk,
                "func": func,
                "axis": axis_number,
                "raw": raw,
                "result_type": result_type,
                "args": args,
                "by_row": by_row,
                "engine": engine,
                "engine_kwargs": engine_kwargs,
                "kwargs": kwargs,
            }
        )

    results = run_parallel_tasks(_apply_chunk, payloads, description="DataFrame.apply")
    if axis_number == 0:
        return _combine_axis_zero(results, self.columns)
    return _combine_axis_one(results, self.index)


def parallel_applymap(self, func, na_action=None, **kwargs):
    from pandarallel.core import get_runtime_config, run_parallel_tasks
    from pandarallel.utils import chunk_slices

    task_slices = chunk_slices(len(self.index), get_runtime_config().nb_workers)
    if len(task_slices) <= 1:
        mapper = getattr(self, "map", None)
        if mapper is not None:
            return mapper(func, na_action=na_action, **kwargs)
        return self.applymap(func, na_action=na_action, **kwargs)

    payloads = [
        {
            "frame": self.iloc[task_slice, :],
            "func": func,
            "na_action": na_action,
            "kwargs": kwargs,
        }
        for task_slice in task_slices
    ]

    results = run_parallel_tasks(
        _applymap_chunk,
        payloads,
        description="DataFrame.applymap",
    )
    combined = pd.concat(results, axis=0)
    return combined.reindex(index=self.index)


def install() -> None:
    patch_method(pd.DataFrame, "parallel_apply", parallel_apply)
    patch_method(pd.DataFrame, "parallel_applymap", parallel_applymap)
